<h1>Tu carrito</h1>
<?php if(!$rows):?><p class="muted">Está vacío. <a href="index.php">Explora el catálogo</a>.</p><?php else:?><table><?php foreach($rows as $p):?><tr><td><?=e($p['name'])?></td><td>× <?=$c[$p['id']]?></td><td><?=money($p['price']*$c[$p['id']])?></td><td><form method="post" action="<?=url('carrito/quitar')?>"><input type="hidden" name="t" value="<?=csrf()?>"><button name="id" value="<?=$p['id']?>" class="link">Quitar</button></form></td></tr><?php endforeach;?><tr><th colspan="2">Total</th><th colspan="2"><?=money($tot)?></th></tr></table>
